    it("should return formatted string when memories come as { results: [...] }", async () => {
      const { retrieveMemories } = require("../src/mem0-utils");

      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => ({
          results: [{ memory: "User likes pizza" }],
        }),
      });

